18	func validateClientMotionMedia(motion *v1pb.MotionMedia, attachmentUID string) (*storepb.MotionMedia, error) {
19		if motion == nil {
20			return nil, nil
21		}
22	
23		if motion.Family != v1pb.MotionMediaFamily_APPLE_LIVE_PHOTO {
24			return nil, status.Errorf(codes.InvalidArgument, "only Apple Live Photo motion metadata can be provided by clients")
25		}
26		if motion.Role != v1pb.MotionMediaRole_STILL && motion.Role != v1pb.MotionMediaRole_VIDEO {
27			return nil, status.Errorf(codes.InvalidArgument, "invalid Apple Live Photo motion role")
28		}
29	
30		storeMotion := convertMotionMediaToStore(motion)
31		if storeMotion.GroupId == "" {
32			return nil, status.Errorf(codes.InvalidArgument, "motion media group_id is required")
33		}
34		if storeMotion.Family == storepb.MotionMediaFamily_ANDROID_MOTION_PHOTO && storeMotion.GroupId == "" {
35			storeMotion.GroupId = attachmentUID
36		}
37	
38		return storeMotion, nil
39	}
